    private static void emit(MatrixStack ms,VertexConsumer out,int light,int overlay,float r,float g,float b,float a,float[][] data) {
        MatrixStack.Entry e=ms.peek();
        for(float[] v:data) out.vertex(e.getPositionMatrix(),v[0],v[1],v[2]).color(r,g,b,a).texture(v[3],v[4]).overlay(overlay).light(light).normal(e.getNormalMatrix(),v[5],v[6],v[7]).next();
    }

